def categorize_task_set(task_set):
    is_implicit = True
    is_constrained = True
    for task_i in task_set:
        if task_i.D != task_i.T:
            is_implicit = False
        if task_i.D > task_i.T:
            is_constrained = False

    if is_implicit:
        return "Implicit Deadlines"
    elif is_constrained:
        return "Constrained Deadlines"
    else:
        return "Arbitrary Deadlines"

def calculate_DT_MIN(task_set):
    min_val = float('inf')
    for task_i in task_set:
        min_val = min(min_val, task_i.D, task_i.T)
    return min_val

def calculate_slot_duration(DT_MIN, delta):
    assert delta >= 1, "delta must be an integer >= 1"
    return DT_MIN / delta

