import math

def jobs(t, p, task_P, tau_hi_p, tau_lo_p):
    total_arrivals = 0
    for task_j in task_P:
        total_arrivals += math.floor(t / task_j.T) + 1
    if tau_hi_p:
        total_arrivals += math.floor(t / tau_hi_p.T) + 1
    if tau_lo_p:
        total_arrivals += math.floor(t / tau_lo_p.T) + 1
    return total_arrivals

